package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.transaction.TransactionDefinition;
import tools.jackson.databind.json.JsonMapper;

/** Full owner metadata views over actual MySQL; fixture births do not authorize execution. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class OwnerJobsReadMySqlTest {
    OwnerJobInputMetadataMySqlTest f;OwnerJobsReadService service;final Actor owner=new Actor("fictional-owner","owner");
    @BeforeEach void setup(){f=new OwnerJobInputMetadataMySqlTest();f.setup();service=new OwnerJobsReadService(f.f.store,f.service,new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.f.f.source));}
    void attempts(){f.save(f.generic());f.f.writer.execute(s->{var records=new JdbcJobRecords(f.f.f.source);String hash=com.lianxibu.site.domain.protocol.CanonicalJson.hash(com.lianxibu.site.domain.protocol.CanonicalJson.Domain.INPUT,f.body);for(int i=1;i<=3;i++){records.prepareAttempt(new JdbcJobRecords.Attempt("fictional-attempt-"+i,f.root,i,"{}",f.root,hash),f.cutoff);if(i<3){f.f.f.jdbc.update("UPDATE jobs SET call_count=? WHERE id=?",i,f.root);f.f.f.jdbc.update("UPDATE jobs SET state=?,usage_json=?,cost_decimal=? WHERE id=?",i==1?"succeeded":"unknown_external","{\"input_tokens\":10,\"prompt_tokens\":10,\"output_tokens\":2}","0.01000000","fictional-attempt-"+i);}}f.f.f.jdbc.update("UPDATE jobs SET state='waiting_retry' WHERE id=?",f.root);return true;});}
    @Test void actualRootOwnsBudgetAndAttemptDoesNotCloneIt(){attempts();var root=service.get(owner,f.root);assertEquals(2,root.callCount());assertEquals(3L,root.maxAttempts());assertEquals(1,root.remainingAttempts());assertFalse(root.retryExhausted());assertEquals(3,root.attempts().size());assertEquals(10L,root.attempts().getFirst().usage().inputTokens());assertEquals("waiting_retry",root.waitingReasons().getFirst());assertEquals(f.root,root.inputSnapshotId());assertEquals("unknown",root.externalResultState());var attempt=service.get(owner,"fictional-attempt-2");assertEquals(0,attempt.callCount());assertNull(attempt.maxAttempts());assertEquals(0,attempt.remainingAttempts());assertEquals(f.root,attempt.inputSnapshotId());assertEquals(root.coverage(),attempt.coverage());assertEquals(1,attempt.attempts().size());assertEquals("unknown",attempt.externalResultState());}
    @Test void originalIntentAggregatesActualRootsWithoutInventingSnapshotOrBudget(){attempts();var intent=service.get(owner,f.intent);assertEquals("partial",intent.coverage().state());assertEquals("fictional-dependency",intent.coverage().missingInputs().getFirst().id());assertNull(intent.inputSnapshotId());assertEquals(0,intent.callCount());assertNull(intent.maxAttempts());assertEquals(0,intent.remainingAttempts());assertTrue(intent.attempts().isEmpty());assertEquals(f.intent,intent.intentId());assertEquals(intent.revision(),intent.intentRevision());}
    @Test void reportDateAndContentMetadataAndWireProjectionContainNoInputBody(){f.save(f.report());var report=service.get(owner,f.root);assertEquals("fictional-report-content",report.contentId());assertEquals(6,report.coverage().missingDates().size());assertEquals(1,report.coverage().noUpdateDates().size());String wire=JsonMapper.shared().writeValueAsString(com.lianxibu.site.controller.jobs.JobsDtos.job(report));assertFalse(wire.contains("bytes_base64"));assertFalse(wire.contains("members"));assertFalse(wire.contains("request_json"));}
    @Test void absenceIsExplicitPendingWhileControlRowsAndPagingRemainHonest(){f.f.writer.execute(s->{var records=new JdbcJobRecords(f.f.f.source);records.ensureIntent(new JdbcJobRecords.Intent(f.intent,"fictional-key",1,"ad_hoc_ai",LocalDate.of(2026,1,4)),f.cutoff);records.createRoot(new JdbcJobRecords.Root(f.root,f.intent,"fictional-key",1,0,"ad_hoc_ai",14),f.cutoff);records.appendDisposition(new JdbcJobRecords.Disposition("fictional-control","fictional-control-key","generation_prepare","{}","fictional-owner","Fictional metadata receipt","{}"),f.cutoff);return true;});var root=service.get(owner,f.root);assertNull(root.inputSnapshotId());assertEquals("partial",root.coverage().state());assertEquals("not_frozen",root.coverage().missingInputs().getFirst().reason());var intent=service.get(owner,f.intent);assertEquals("partial",intent.coverage().state());var control=service.get(owner,"fictional-control");assertEquals("no_input",control.coverage().state());assertNull(control.inputSnapshotId());var page=service.list(owner,"logical_task",null,1,10);assertEquals(1,page.total());assertEquals(1,page.items().size());assertTrue(service.list(owner,"logical_task",null,2,10).items().isEmpty());assertEquals(1,service.list(owner,"logical_task",null,2,10).total());}
    @Test void nativeOccupiedSlotMustReferenceActualAiAttempt(){attempts();f.f.f.jdbc.update("UPDATE worker_lock SET slot_state='occupied',job_id='fictional-attempt-2',slot_revision=5");var root=service.get(owner,f.root);assertEquals("occupied",root.slotState());assertEquals(5,root.slotRevision());assertEquals("fictional-attempt-2",root.occupiedAttemptId());f.f.f.jdbc.update("UPDATE worker_lock SET job_id=?",f.intent);assertUnavailable(()->service.get(owner,f.root));}
    @Test void deniedActorsReadNoSqlAndUnknownIdentifierIsNotFound(){f.f.f.jdbc.execute("DROP TABLE jobs");assertEquals(IdentityService.Refusal.UNAUTHENTICATED,assertThrows(IdentityService.Rejected.class,()->service.get(null,f.root)).refusal());assertEquals(IdentityService.Refusal.FORBIDDEN,assertThrows(IdentityService.Rejected.class,()->service.list(new Actor("fictional-member","member"),null,null,1,10)).refusal());setup();assertEquals(IdentityService.Refusal.NOT_FOUND,assertThrows(IdentityService.Rejected.class,()->service.get(owner,"fictional-absent")).refusal());}
    @Test void originalInputAssociationAndUsageDamageAreFixedUnavailable(){attempts();f.f.f.jdbc.update("UPDATE jobs SET snapshot_owner_id=? WHERE id='fictional-attempt-2'",f.intent);assertUnavailable(()->service.get(owner,"fictional-attempt-2"));setup();attempts();f.f.f.jdbc.update("UPDATE jobs SET usage_json='{\"input_tokens\":10,\"prompt_tokens\":11}' WHERE id='fictional-attempt-1'");assertUnavailable(()->service.get(owner,f.root));setup();f.save(f.generic());f.f.f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE record_kind='snapshot_part'",new byte[32]);assertUnavailable(()->service.get(owner,f.root));}
    @Test void sameActualRepeatableReadPreservesNativeBudgetAcrossConcurrentCommit(){f.save(f.generic());f.f.writer.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);f.f.read(()->{assertEquals(0,service.get(owner,f.root).callCount());f.f.writer.execute(s->{f.f.f.jdbc.update("UPDATE jobs SET call_count=1,revision=revision+1 WHERE id=?",f.root);return true;});assertEquals(0,service.get(owner,f.root).callCount());return true;});assertEquals(1,service.get(owner,f.root).callCount());}
    @Test void exhaustedBudgetIsOnlyRootMetadataAndPageInputCapacityRefusesWholePage(){attempts();f.f.f.jdbc.update("UPDATE jobs SET call_count=3,state='failed' WHERE id=?",f.root);assertTrue(service.get(owner,f.root).retryExhausted());assertEquals(0,service.get(owner,f.root).remainingAttempts());assertFalse(service.get(owner,"fictional-attempt-2").retryExhausted());setup();var body=(tools.jackson.databind.node.ObjectNode)f.generic();((tools.jackson.databind.node.ObjectNode)body.get("members").get(0)).put("body_text","F".repeat(3500000));f.save(body);String raw=JdbcFrozenInputs.canonical(body),hash=com.lianxibu.site.domain.protocol.CanonicalJson.hash(com.lianxibu.site.domain.protocol.CanonicalJson.Domain.INPUT,body);f.f.writer.execute(s->{var records=new JdbcJobRecords(f.f.f.source);for(int i=1;i<5;i++){String id="fictional-large-root-"+i;records.createRoot(new JdbcJobRecords.Root(id,f.intent,"fictional-metadata-key",1,i,"ad_hoc_ai",14),f.cutoff);f.inputs.save(id,raw,hash,f.cutoff);f.f.f.jdbc.update("UPDATE jobs SET input_state='ready',coverage_state='partial',missing_inputs_json='[\"fictional-dependency\"]',input_cutoff_at=? WHERE id=?",java.sql.Timestamp.from(f.cutoff),id);}return true;});assertEquals(4,service.list(owner,"logical_task",null,1,4).items().size());assertUnavailable(()->service.list(owner,"logical_task",null,1,5));}
    void assertUnavailable(Runnable operation){var error=assertThrows(IdentityService.Rejected.class,operation::run);assertEquals(IdentityService.Refusal.TEMPORARILY_UNAVAILABLE,error.refusal());assertEquals("TEMPORARILY_UNAVAILABLE",error.getMessage());}
}
